(() => {
'use strict';
const M=window.CourseModel,$=id=>document.getElementById(id);
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const panelNames=['start','elements','classify','process','methods','project','sources'];
function navigate(){const requested=location.hash.slice(1),name=panelNames.includes(requested)?requested:'start';document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==name);document.querySelectorAll('[data-panel]').forEach(a=>{const active=a.dataset.panel===name;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});document.title=`${document.querySelector(`[data-panel="${name}"]`).textContent.slice(3)} · 第一章`;}
window.addEventListener('hashchange',navigate);navigate();
const opening={small:'直接行动需要可行性证据：预算、场地、成本与需求是否足以支撑小店？请把关键假设写下来。',research:'调查或试营业也是方案，有时间与费用成本。需要说明它会改变哪项判断，以及何时停止调查。',wait:'暂缓可以保留资源，但也可能失去机会。需要说明等待什么信息、在什么条件下重新考虑投资。'};
document.querySelectorAll('[data-choice]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-choice]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));});$('opening-feedback').textContent=opening[b.dataset.choice];}));
const options=[['state','自然状态'],['criterion','决策准则'],['actor','决策者'],['result','决策结果'],['goal','决策目标'],['action','决策方案']];
$('element-exercise').innerHTML=M.elements.map((e,i)=>`<div class="form-row"><label for="element-${e.key}">${i+1}. ${escape(e.text)}</label><select id="element-${e.key}"><option value="">请选择要素</option>${options.map(([k,n])=>`<option value="${k}">${n}</option>`).join('')}</select><div class="result-line" id="result-${e.key}"></div></div>`).join('');
$('check-elements').addEventListener('click',()=>{let score=0,answered=0;for(const e of M.elements){const value=$(`element-${e.key}`).value;if(value)answered++;const right=value===e.key;if(right)score++;$(`result-${e.key}`).textContent=(right?'✓ 正确。':value?`请再辨析：这是“${e.name}”。`:'尚未选择。')+(value?' '+e.explain:'');$(`result-${e.key}`).style.color=right?'var(--green)':'var(--red)';}$('elements-feedback').textContent=`已作答 ${answered} / 6，归类正确 ${score} / 6。${score===6?'继续检查：目标与准则的区别，你能用自己的话说明吗？':'对照每项解释，修改后可再次检查。'}`;});
$('reset-elements').addEventListener('click',()=>{M.elements.forEach(e=>{$(`element-${e.key}`).value='';$(`result-${e.key}`).textContent='';});$('elements-feedback').textContent='';});
$('taxonomy').innerHTML=M.taxonomy.map(([a,b,c])=>`<article><h3>${escape(a)}</h3><p><strong>${escape(b)}</strong><br>${escape(c)}</p></article>`).join('');
function scenarioState(){return{information:document.querySelector('input[name="information"]:checked').value,multi:$('multi').checked,staged:$('staged').checked,strategic:$('strategic').checked};}
function updateScenario(){const r=M.classify(scenarioState());$('scenario-tags').innerHTML=r.tags.map(t=>`<span class="tag">${escape(t)}</span>`).join('');$('scenario-explanation').textContent=r.explanation;$('scenario-methods').textContent=r.methods;$('scenario-caveat').textContent=r.caveat;return r;}
function configureScenario(s){M.classify(s);document.querySelector(`input[name="information"][value="${s.information}"]`).checked=true;['multi','staged','strategic'].forEach(k=>$(k).checked=s[k]);return updateScenario();}
document.querySelectorAll('input[name="information"],#multi,#staged,#strategic').forEach(el=>el.addEventListener('change',updateScenario));$('reset-scenario').addEventListener('click',()=>configureScenario({information:'risk',multi:false,staged:false,strategic:false}));updateScenario();
$('process-steps').innerHTML=M.steps.map(([title],i)=>`<button class="process-step" data-step="${i}" aria-pressed="false"><strong>0${i+1}</strong>${title}</button>`).join('');
function showStep(i){document.querySelectorAll('[data-step]').forEach(b=>{const active=Number(b.dataset.step)===i;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));});$('process-detail').innerHTML=`<h3>${M.steps[i][0]}</h3><p>${M.steps[i][1]}</p>`;}
document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>showStep(Number(b.dataset.step))));showStep(0);
function updateEvent(){$('event-feedback').textContent=M.events[$('event-select').value];}$('event-select').addEventListener('change',updateEvent);updateEvent();
$('principles').innerHTML=M.principles.map(([a,b],i)=>`<article class="principle"><strong>${i+1}. ${a}原则</strong><p>${b}</p></article>`).join('');
function carState(){return{oil:Number($('oil').value),saving:Number($('saving').value),burden:Number($('burden').value)};}
const num=(v,d=0)=>v.toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d});
function updateCar(){const s=carState(),r=M.carModel(s);$('oil-value').textContent=num(s.oil,1)+' 倍';$('saving-value').textContent=s.saving+'%';$('burden-value').textContent=num(s.burden,1)+'%';$('car-price').textContent=r.feasible?num(r.maxPrice)+' 美元':'当前目标不可行';$('car-explanation').textContent=`改进后的年燃油费为 ${num(r.newFuel,2)} 美元，占年收入 ${num(r.newFuelPercent,3)}%。`;$('car-feasible').textContent=r.feasible?`剩余 ${num(r.allowedAnnual-r.newFuel,2)} 美元/年可用于分摊购车费用。`:'即使车价为零，燃油负担也超过目标。需要进一步节油或调整目标。';$('car-formula').textContent=`最高车价 = 5 × (${num(r.allowedAnnual,2)} − ${num(r.newFuel,2)}) = ${num(r.maxPrice,2)} 美元`;
 const rows=[['原始情境',r.baseCarPercent,r.baseFuelPercent],['仅油价变化',r.baseCarPercent,r.shockFuelPercent],[r.feasible?'节油 + 最高可行车价':'节油 + 零车价',r.newCarPercent,r.newFuelPercent]];
 $('car-bars').innerHTML=rows.map(([name,a,b])=>`<div class="bar-row"><div class="bar-label"><span>${name}</span><strong>${num(a+b,2)}%</strong></div><div class="bar-track" role="img" aria-label="${name}，购车 ${num(a,2)}%，燃油 ${num(b,2)}%"><span class="bar-car" style="width:${a/30*100}%"></span><span class="bar-fuel" style="width:${b/30*100}%"></span></div></div>`).join('');return r;}
['oil','saving','burden'].forEach(id=>$(id).addEventListener('input',updateCar));$('reset-car').addEventListener('click',()=>{$('oil').value=4;$('saving').value=40;$('burden').value=12.2;updateCar();});updateCar();
const storageKey='decision-course-ch1-canvas-v1';let draft={},storageAvailable=true;try{const parsed=JSON.parse(localStorage.getItem(storageKey)||'{}');if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))for(const [k]of M.canvas)if(typeof parsed[k]==='string')draft[k]=parsed[k].slice(0,5000);}catch{storageAvailable=false;}
$('canvas-fields').innerHTML=M.canvas.map(([key,title,hint])=>`<div class="field"><label for="canvas-${key}">${title}</label><small>${hint}</small><textarea id="canvas-${key}" maxlength="5000" placeholder="用你自己的语言填写…"></textarea></div>`).join('');
for(const [k]of M.canvas){$(`canvas-${k}`).value=draft[k]||'';$(`canvas-${k}`).addEventListener('input',saveCanvas);}
function readCanvas(){return Object.fromEntries(M.canvas.map(([k])=>[k,$(`canvas-${k}`).value]));}
function updateProgress(){const count=Object.values(readCanvas()).filter(v=>v.trim()).length;$('draft-progress').textContent=`画布填写：${count} / 10`;$('draft-bar').style.width=`${count*10}%`;}
function saveCanvas(){draft=readCanvas();try{localStorage.setItem(storageKey,JSON.stringify(draft));storageAvailable=true;$('canvas-status').textContent='草稿已保存在本设备';}catch{storageAvailable=false;$('canvas-status').textContent='浏览器未允许保存，请导出画布保留内容。';}updateProgress();}
updateProgress();if(!storageAvailable)$('canvas-status').textContent='浏览器未允许保存，可导出画布保留内容。';
$('fill-canvas').addEventListener('click',()=>{for(const [k,,,example]of M.canvas)if(!$(`canvas-${k}`).value.trim())$(`canvas-${k}`).value=example;saveCanvas();$('canvas-status').textContent=(storageAvailable?'示例已补入空白项并保存。':'示例已补入空白项；请导出保留。')+'请修改为你的小组方案。';});
$('export-canvas').addEventListener('click',()=>{const data=readCanvas();const content='# 第一章：决策问题画布\n\n情境：校园咖啡店（教学模拟）\n\n'+M.canvas.map(([k,t])=>'## '+t+'\n\n'+(data[k].trim()||'（待填写）')).join('\n\n')+'\n\n说明：事实、假设和建议应分别标注；请保留数据来源和修改理由。\n';const blob=new Blob(['\uFEFF'+content],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='第一章-决策问题画布.md';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);$('canvas-status').textContent='画布已生成下载；请检查浏览器下载列表。';});
$('quiz-questions').innerHTML=M.quiz.map((q,i)=>`<div class="quiz-item"><fieldset><legend>${i+1}. ${escape(q.q)}</legend>${q.options.map((o,j)=>`<label class="radio-line"><input type="radio" name="quiz-${i}" value="${j}">${escape(o)}</label>`).join('')}</fieldset><div id="quiz-explain-${i}" class="result-line"></div></div>`).join('');
$('quiz-form').addEventListener('submit',e=>{e.preventDefault();const answers=M.quiz.map((_,i)=>{const x=document.querySelector(`input[name="quiz-${i}"]:checked`);return x?Number(x.value):null;}),r=M.gradeQuiz(answers);if(!r.complete){$('quiz-feedback').textContent='还有题目未作答，请先完成全部 5 题。';return;}M.quiz.forEach((q,i)=>{$(`quiz-explain-${i}`).textContent=(answers[i]===q.correct?'✓ 正确。':'需要修正。')+q.explain;});$('quiz-feedback').innerHTML=`<span class="score">${r.score} / ${r.total}</span><br>${r.score===r.total?'概念判断已完成。试着不看答案，向同伴解释每一题的依据。':'请对照解释，回到相应知识点后重做。'}`;});
$('quiz-form').addEventListener('reset',()=>{M.quiz.forEach((_,i)=>$(`quiz-explain-${i}`).textContent='');$('quiz-feedback').textContent='';});
// Optional WebMCP: the same state/actions as the visible scenario controls.
const context=document.modelContext;if(context?.registerTool){const lifecycle=new AbortController();const tools=[{name:'read_decision_scenario',title:'读取决策情境',description:'读取第一章分类实验的当前输入和解释，不修改状态。',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute:()=>({state:scenarioState(),result:M.classify(scenarioState())})},{name:'configure_decision_scenario',title:'配置决策情境',description:'更新第一章分类实验的可见选项并返回分类解释。',inputSchema:{type:'object',properties:{information:{type:'string',enum:['known','risk','unknown']},multi:{type:'boolean'},staged:{type:'boolean'},strategic:{type:'boolean'}},required:['information','multi','staged','strategic'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>{if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['information','multi','staged','strategic'].includes(k)))throw Error('无效参数');M.classify(input);const result=configureScenario(input);location.hash='classify';navigate();return{state:scenarioState(),result};}}];for(const tool of tools){try{Promise.resolve(context.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
})();
